import{_ as n,o as h,c as i,a2 as c}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Chỉ mục Điều khoản Pháp lý","description":"","frontmatter":{},"headers":[],"relativePath":"vi/92-法律条文索引.md","filePath":"vi/92-法律条文索引.md","lastUpdated":null}'),g={name:"vi/92-法律条文索引.md"};function u(d,t,a,o,r,l){return h(),i("div",null,[...t[0]||(t[0]=[c('<h1 id="chi-muc-đieu-khoan-phap-ly" tabindex="-1">Chỉ mục Điều khoản Pháp lý <a class="header-anchor" href="#chi-muc-đieu-khoan-phap-ly" aria-label="Permalink to &quot;Chỉ mục Điều khoản Pháp lý&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>92</td></tr><tr><td>Mô-đun</td><td>Phụ lục và Tài liệu Tham khảo</td></tr><tr><td>Từ khóa chính</td><td>chỉ mục pháp lý, Hiến pháp Cộng sinh, luật lao động, luật bảo vệ người tiêu dùng, luật hỗ trợ</td></tr></tbody></table><h2 id="_1-mo-ta-chi-muc" tabindex="-1">1. Mô tả Chỉ mục <a class="header-anchor" href="#_1-mo-ta-chi-muc" aria-label="Permalink to &quot;1. Mô tả Chỉ mục&quot;">​</a></h2><p>Chỉ mục này chứa các tài liệu pháp lý chính hiện đang có hiệu lực và các điều khoản cốt lõi của Văn minh Cộng sinh Mỏ neo, được sắp xếp theo thứ bậc pháp lý và bộ phận. Phạm vi chỉ mục bao gồm &quot;Hiến pháp Cộng sinh&quot;, &quot;Luật Lao động Cộng sinh&quot;, &quot;Luật Bảo vệ Người tiêu dùng&quot;, cũng như năm luật hỗ trợ về giáo dục, y tế, nhà ở, môi trường và chống độc quyền. Mỗi mục nhập chỉ mục liệt kê tên luật, số điều khoản và tóm tắt nội dung cốt lõi của điều khoản. Chỉ mục này là một công cụ tham khảo; đối với văn bản đầy đủ của các điều khoản pháp lý và giải thích tư pháp, vui lòng tham khảo văn bản chính thức của từng luật.</p><h2 id="_2-hien-phap-cong-sinh" tabindex="-1">2. Hiến pháp Cộng sinh <a class="header-anchor" href="#_2-hien-phap-cong-sinh" aria-label="Permalink to &quot;2. Hiến pháp Cộng sinh&quot;">​</a></h2><p>&quot;Hiến pháp Cộng sinh&quot; là luật cơ bản của Văn minh Cộng sinh Mỏ neo, có hiệu lực pháp lý cao nhất, được ban hành vào thời điểm thành lập chính thức văn minh cộng sinh.</p><table tabindex="0"><thead><tr><th>Số điều khoản</th><th>Nội dung cốt lõi</th></tr></thead><tbody><tr><td>Điều 1</td><td>Xác định Hengyuanzhou (Vũ trụ Nguồn gốc Wanling Hengmao) là miền trị lý của Văn minh Cộng sinh Mỏ neo; mục đích cơ bản của văn minh cộng sinh là đạt được cộng sinh của tất cả các chủng tộc và thăng hoa chiều không gian vũ trụ</td></tr><tr><td>Điều 2</td><td>Xác định chủ nghĩa chống cướp bóc làm lập trường cơ bản của văn minh; cấm mọi hình thức tu luyện kiểu cướp bóc và cướp bóc tài nguyên</td></tr><tr><td>Điều 3</td><td>Xác định &quot;trả lại quyền lựa chọn định mệnh và tiến hóa cho tất cả chúng sinh có tri giác&quot; làm khái niệm cốt lõi của văn minh</td></tr><tr><td>Điều 4</td><td>Xác định nhiều lao động nhiều thu nhập, tự trưởng thành, ai cũng có con đường, tất cả các chủng tộc cùng tiến bộ làm chính sách cơ bản của văn minh</td></tr><tr><td>Điều 5</td><td>Xác định hệ thống mở cửa miễn phí của ba trăm bộ hệ thống tu luyện nguồn gốc; không tổ chức hay cá nhân nào được độc quyền hóa sự cho phép truyền đạt hệ thống tu luyện</td></tr><tr><td>Điều 6</td><td>Xác định cơ chế hợp đồng sản xuất chung làm hệ thống phân bổ tài nguyên cơ bản</td></tr><tr><td>Điều 7</td><td>Xác định chiến lược kích hoạt 20% làm mục tiêu quốc gia theo giai đoạn</td></tr><tr><td>Điều 8</td><td>Xác định nguyên tắc dựa trên thực tế; thế giới thực là thế giới thực duy nhất, các thiết lập hư cấu không có hiệu lực pháp lý</td></tr><tr><td>Điều 9</td><td>Xác định con đường thăng hoa chiều không gian bốn giai đoạn làm chiến lược phát triển dài hạn của văn minh</td></tr><tr><td>Điều 10</td><td>Xác định nguyên tắc bình đẳng tất cả các chủng tộc; mọi hình thức sự sống đều bình đẳng trước pháp luật</td></tr><tr><td>Điều 11</td><td>Xác định nguyên tắc tiến hóa cộng sinh; tiến hóa cá nhân không được thực hiện bằng cách hy sinh quyền tiến hóa của cá nhân hoặc tập thể khác</td></tr><tr><td>Điều 12</td><td>Xác định nguyên tắc nhiều lao động nhiều thu nhập; phân bổ tài nguyên lấy đóng góp làm cơ sở cốt lõi</td></tr><tr><td>Điều 13</td><td>Xác định nguyên tắc tự trưởng thành; tôn trọng quyền tự chủ lựa chọn tiến hóa của mỗi sự sống</td></tr><tr><td>Điều 14</td><td>Xác định nguyên tắc ai cũng có con đường; nhà nước có nghĩa vụ cung cấp cho mỗi sự sống con đường tiến hóa cơ bản và bảo đảm tài nguyên</td></tr><tr><td>Điều 15</td><td>Xác định nguyên tắc bền vững; mọi phát triển phải xem xét tính bền vững của nguồn gốc vũ trụ</td></tr><tr><td>Điều 16-25</td><td>Quy định các quyền cơ bản của tất cả chúng sinh có tri giác: quyền lựa chọn tiến hóa, quyền获得 tài nguyên tu luyện, quyền bảo vệ bình đẳng, quyền tham gia cộng sinh, quyền bảo tồn văn hóa, quyền cứu trợ và kháng cáo, quyền tự do nhân thân, quyền phẩm giá con người, quyền tự do tín ngưỡng, quyền tự do biểu đạt</td></tr><tr><td>Điều 26-31</td><td>Quy định các nghĩa vụ cơ bản của tất cả chúng sinh có tri giác: nghĩa vụ tuân thủ pháp luật, nghĩa vụ duy trì trật tự cộng sinh, nghĩa vụ đóng góp lao động, nghĩa vụ bảo vệ môi trường, nghĩa vụ tôn trọng quyền của người khác, nghĩa vụ hướng dẫn tu luyện viên cấp dưới</td></tr><tr><td>Điều 32</td><td>Xác định Hội đồng Mỏ neo là cơ quan quyền lực cao nhất, bao gồm đại diện của tất cả các chủng tộc theo tỷ lệ</td></tr><tr><td>Điều 33</td><td>Xác định Ủy ban Hành chính Cộng sinh là cơ quan hành chính cao nhất</td></tr><tr><td>Điều 34</td><td>Xác định Tòa án Cộng sinh là cơ quan tư pháp cao nhất, thực hiện quyền tư pháp một cách độc lập</td></tr><tr><td>Điều 35</td><td>Xác định Ủy ban Giám sát Mỏ neo là cơ quan giám sát độc lập</td></tr><tr><td>Điều 36</td><td>Quy định thủ tục lập pháp: dự án luật được thông qua bằng đa số hơn nửa của Hội đồng Mỏ neo</td></tr><tr><td>Điều 37</td><td>Quy định thủ tục sửa đổi hiến pháp: phải được thông qua bằng đa số hơn hai phần ba của Hội đồng Mỏ neo và được phê duyệt bởi hơn nửa cuộc trưng cầu dân ý quốc gia</td></tr><tr><td>Điều 38</td><td>Xác định hệ thống xem xét vi hiến; Tòa án Cộng sinh có quyền tuyên bố vô hiệu các luật vi phạm Hiến pháp</td></tr><tr><td>Điều 39</td><td>Xác định hệ thống kiện tụng hiến pháp; tất cả chúng sinh có tri giác có thể trực tiếp khởi kiện dựa trên Hiến pháp</td></tr><tr><td>Điều 40</td><td>Quy định hệ thống tự trị địa phương; mỗi miền sao và mỗi mặt phẳng thực hiện tự trị trong khuôn khổ hiến pháp</td></tr><tr><td>Điều 41</td><td>Xác định hệ thống cộng hòa tất cả các chủng tộc; tất cả các nhóm dân tộc đều bình đẳng trong văn minh cộng sinh và thực hiện tự trị khu vực</td></tr><tr><td>Điều 42</td><td>Quy định hệ thống kinh tế của văn minh cộng sinh: dựa trên hợp đồng sản xuất chung, nhiều nền kinh tế sở hữu cùng phát triển</td></tr><tr><td>Điều 43</td><td>Quy định hệ thống sở hữu nhà nước và phân bổ công bằng tài nguyên tu luyện</td></tr><tr><td>Điều 44</td><td>Xác định hệ thống công bằng giáo dục, bảo đảm quyền giáo dục bình đẳng của mỗi sự sống</td></tr><tr><td>Điều 45</td><td>Xác định hệ thống bảo đảm y tế toàn dân</td></tr><tr><td>Điều 46</td><td>Xác định hệ thống bảo đảm nhà ở, bảo đảm quyền nhà ở cơ bản của mỗi sự sống</td></tr><tr><td>Điều 47</td><td>Quy định các nguyên tắc cơ bản của tương tác giữa các mặt phẳng; không được thực hiện bất kỳ chuyến du lịch giữa các mặt phẳng không được phép nếu không có sự cho phép</td></tr><tr><td>Điều 48</td><td>Quy định sản phẩm hợp pháp của hoạt động khảo cổ chỉ giới hạn ở tri thức trừu tượng và thông tin; cấm mang lại vật chất và năng lượng</td></tr><tr><td>Điều 49</td><td>Quy định các nguyên tắc cơ bản của hồi quy thời gian; phải tuân theo nguyên tắc quan sát trước, sau đó can thiệp hạn chế</td></tr><tr><td>Điều 50</td><td>Quy định quyền giải thích Hiến pháp thuộc về Tòa án Cộng sinh, và quyền sửa đổi Hiến pháp thuộc về Hội đồng Mỏ neo</td></tr></tbody></table><h2 id="_3-luat-lao-đong-cong-sinh" tabindex="-1">3. Luật Lao động Cộng sinh <a class="header-anchor" href="#_3-luat-lao-đong-cong-sinh" aria-label="Permalink to &quot;3. Luật Lao động Cộng sinh&quot;">​</a></h2><p>&quot;Luật Lao động Cộng sinh&quot; là luật cơ bản điều chỉnh quan hệ lao động và bảo vệ quyền lợi của người lao động, lấy Điều 42 của Hiến pháp Cộng sinh làm cơ sở lập pháp.</p><table tabindex="0"><thead><tr><th>Số điều khoản</th><th>Nội dung cốt lõi</th></tr></thead><tbody><tr><td>Điều 1</td><td>Mục đích lập pháp: điều chỉnh quan hệ lao động, bảo vệ quyền lợi hợp pháp của người lao động, và xây dựng quan hệ lao động hài hòa và cộng sinh</td></tr><tr><td>Điều 2</td><td>Phạm vi áp dụng: tất cả các quan hệ lao động trong Hengyuanzhou, bao gồm lao động vật chất, lao động tu luyện và lao động sáng tạo</td></tr><tr><td>Điều 3</td><td>Xác định nguyên tắc việc làm bình đẳng cho người lao động; cấm phân biệt đối xử trong việc làm dựa trên chủng tộc, giới tính, cấp độ tu luyện hoặc xuất xứ</td></tr><tr><td>Điều 4</td><td>Xác định nguyên tắc tự do lựa chọn nghề nghiệp cho người lao động; cấm lao động cưỡng bức và chế độ nô lệ</td></tr><tr><td>Điều 5</td><td>Quy định hệ thống hợp đồng lao động; khi thiết lập quan hệ lao động, phải ký hợp đồng lao động bằng văn bản</td></tr><tr><td>Điều 6</td><td>Quy định các điều khoản cần thiết của hợp đồng lao động: thời hạn hợp đồng, nội dung công việc, tiền công lao động, thời gian làm việc, bảo vệ lao động, bảo hiểm xã hội</td></tr><tr><td>Điều 7</td><td>Xác định hệ thống làm việc tám giờ và hệ thống thời gian làm việc không quá bốn mươi tư giờ mỗi tuần</td></tr><tr><td>Điều 8</td><td>Quy định giới hạn làm thêm giờ: làm thêm giờ hàng ngày không được quá một giờ, trường hợp đặc biệt không được quá ba giờ, làm thêm giờ hàng tháng không được quá ba mươi sáu giờ</td></tr><tr><td>Điều 9</td><td>Quy định tiêu chuẩn tiền công làm thêm giờ: 1,5 lần tiền công cho làm thêm giờ vào ngày làm việc, 2 lần tiền công cho làm thêm giờ vào ngày nghỉ, 3 lần tiền công cho làm thêm giờ vào ngày lễ pháp lý</td></tr><tr><td>Điều 10</td><td>Xác định hệ thống bảo đảm tiền công tối thiểu; tiêu chuẩn tiền công tối thiểu do mỗi miền sao đặt ra theo điều kiện địa phương</td></tr><tr><td>Điều 11</td><td>Quy định hệ thống thanh toán tiền công: tiền công phải được trả hàng tháng cho chính người lao động dưới dạng tiền tệ, và không được khấu trừ hoặc chậm trễ không có lý do</td></tr><tr><td>Điều 12</td><td>Xác định nguyên tắc phân bổ nhiều lao động nhiều thu nhập; thực hiện hệ thống phân bổ với phân bổ theo lao động làm chủ thể và nhiều phương pháp phân bổ cùng tồn tại</td></tr><tr><td>Điều 13</td><td>Quy định hệ thống an toàn và vệ sinh lao động; người sử dụng lao động phải cung cấp cho người lao động các điều kiện an toàn và vệ sinh lao động phù hợp với tiêu chuẩn</td></tr><tr><td>Điều 14</td><td>Quy định bảo vệ các nhóm đặc biệt: bảo vệ lao động đặc biệt cho người lao động vị thành niên, người lao động nữ, người lao động khuyết tật và người lao động tu luyện cấp thấp</td></tr><tr><td>Điều 15</td><td>Xác định hệ thống đào tạo nghề; người sử dụng lao động có nghĩa vụ thực hiện đào tạo kỹ năng nghề cho người lao động</td></tr><tr><td>Điều 16</td><td>Quy định quyền lợi lao động của người tu luyện: lao động tu luyện cũng được luật này bảo vệ; quyền sở hữu kết quả tu luyện được thỏa thuận bằng hợp đồng</td></tr><tr><td>Điều 17</td><td>Xác định hệ thống bảo hiểm xã hội của người lao động: bảo hiểm hưu trí, bảo hiểm y tế, bảo hiểm thất nghiệp, bảo hiểm tai nạn lao động, bảo hiểm sinh đẻ</td></tr><tr><td>Điều 18</td><td>Quy định hệ thống phúc lợi người lao động; người sử dụng lao động phải cung cấp các đãi ngộ phúc lợi cần thiết cho người lao động</td></tr><tr><td>Điều 19</td><td>Xác định hệ thống giải quyết tranh chấp lao động: cơ chế giải quyết bốn cấp độ đàm phán, hòa giải, trọng tài và kiện tụng</td></tr><tr><td>Điều 20</td><td>Quy định hệ thống công đoàn; người lao động có quyền tổ chức và tham gia công đoàn theo luật để bảo vệ quyền lợi hợp pháp của mình</td></tr><tr><td>Điều 21</td><td>Quy định hệ thống hợp đồng tập thể; công đoàn đại diện cho người lao động ký hợp đồng tập thể với người sử dụng lao động</td></tr><tr><td>Điều 22</td><td>Quy định các quy chế của người sử dụng lao động phải được thảo luận bởi đại hội đại biểu người lao động hoặc toàn bộ người lao động</td></tr><tr><td>Điều 23</td><td>Quy định các điều kiện và thủ tục chấm dứt hợp đồng lao động</td></tr><tr><td>Điều 24</td><td>Quy định hệ thống bồi thường kinh tế; người sử dụng lao động phải trả bồi thường kinh tế khi chấm dứt hợp đồng lao động theo luật</td></tr><tr><td>Điều 25</td><td>Quy định hệ thống bồi thường cho việc chấm dứt hợp đồng lao động bất hợp pháp</td></tr><tr><td>Điều 26</td><td>Xác định hệ thống quản lý派遣 lao động, quy định việc làm派遣 lao động</td></tr><tr><td>Điều 27</td><td>Quy định các quy tắc đặc biệt cho việc làm bán thời gian</td></tr><tr><td>Điều 28</td><td>Quy định hệ thống giám sát và kiểm tra; các bộ phận hành chính lao động giám sát và kiểm tra việc tuân thủ pháp luật và quy định lao động của người sử dụng lao động theo luật</td></tr><tr><td>Điều 29</td><td>Quy định trách nhiệm pháp lý: người sử dụng lao động vi phạm luật này sẽ chịu trách nhiệm hành chính, dân sự và hình sự theo luật</td></tr><tr><td>Điều 30</td><td>Quy định ngày hiệu lực và quyền giải thích của luật này</td></tr></tbody></table><h2 id="_4-luat-bao-ve-nguoi-tieu-dung" tabindex="-1">4. Luật Bảo vệ Người tiêu dùng <a class="header-anchor" href="#_4-luat-bao-ve-nguoi-tieu-dung" aria-label="Permalink to &quot;4. Luật Bảo vệ Người tiêu dùng&quot;">​</a></h2><p>&quot;Luật Bảo vệ Người tiêu dùng&quot; là luật cơ bản bảo vệ quyền lợi hợp pháp của người tiêu dùng và quy định hành vi của nhà kinh doanh.</p><table tabindex="0"><thead><tr><th>Số điều khoản</th><th>Nội dung cốt lõi</th></tr></thead><tbody><tr><td>Điều 1</td><td>Mục đích lập pháp: bảo vệ quyền lợi hợp pháp của người tiêu dùng, duy trì trật tự kinh tế xã hội, và thúc đẩy sự phát triển lành mạnh của kinh tế thị trường cộng sinh</td></tr><tr><td>Điều 2</td><td>Phạm vi áp dụng: bảo vệ quyền lợi của người tiêu dùng trong Hengyuanzhou mua, sử dụng hàng hóa hoặc nhận dịch vụ cho nhu cầu tiêu dùng hàng ngày</td></tr><tr><td>Điều 3</td><td>Xác định các nguyên tắc cơ bản của giao dịch giữa nhà kinh doanh và người tiêu dùng: tự nguyện, bình đẳng, công bằng, trung thực và tín nhiệm</td></tr><tr><td>Điều 4</td><td>Xác định nguyên tắc bảo vệ nhà nước đối với quyền lợi hợp pháp của người tiêu dùng; nhà nước thực hiện các biện pháp để bảo đảm người tiêu dùng thực hiện quyền của mình theo luật</td></tr><tr><td>Điều 5</td><td>Quy định chín quyền cơ bản của người tiêu dùng: quyền an toàn, quyền biết, quyền tự chủ lựa chọn, quyền giao dịch công bằng, quyền bồi thường, quyền kết hội, quyền nhận biết, quyền được tôn trọng, quyền giám sát</td></tr><tr><td>Điều 6</td><td>Quy định quyền an toàn của người tiêu dùng: người tiêu dùng được hưởng quyền không bị tổn hại an toàn nhân thân và tài sản khi mua, sử dụng hàng hóa và nhận dịch vụ</td></tr><tr><td>Điều 7</td><td>Quy định quyền biết của người tiêu dùng: người tiêu dùng được hưởng quyền biết tình hình thực tế của hàng hóa họ mua hoặc sử dụng hoặc dịch vụ họ nhận</td></tr><tr><td>Điều 8</td><td>Quy định quyền tự chủ lựa chọn của người tiêu dùng: người tiêu dùng được hưởng quyền tự chủ lựa chọn hàng hóa hoặc dịch vụ</td></tr><tr><td>Điều 9</td><td>Quy định quyền giao dịch công bằng của người tiêu dùng: người tiêu dùng được hưởng quyền giao dịch công bằng và có quyền từ chối hành vi giao dịch cưỡng bức</td></tr><tr><td>Điều 10</td><td>Quy định quyền bồi thường của người tiêu dùng: người tiêu dùng bị tổn hại nhân thân hoặc tài sản do mua, sử dụng hàng hóa hoặc nhận dịch vụ được hưởng quyền được bồi thường theo luật</td></tr><tr><td>Điều 11</td><td>Quy định các nghĩa vụ cơ bản của nhà kinh doanh: thực hiện nghĩa vụ pháp lý và hợp đồng, chấp nhận giám sát, bảo đảm an toàn, cung cấp thông tin trung thực, phát hành chứng từ, bảo đảm chất lượng, thực hiện ba bảo đảm, không được giao dịch không công bằng, không được xâm phạm nhân cách</td></tr><tr><td>Điều 12</td><td>Quy định nghĩa vụ bảo đảm an toàn của nhà kinh doanh: nhà kinh doanh phải bảo đảm hàng hóa hoặc dịch vụ họ cung cấp phù hợp với yêu cầu bảo vệ an toàn nhân thân và tài sản</td></tr><tr><td>Điều 13</td><td>Quy định nghĩa vụ công bố thông tin của nhà kinh doanh: nhà kinh doanh phải cung cấp cho người tiêu dùng thông tin trung thực về hàng hóa hoặc dịch vụ, và không được quảng cáo sai sự thật hoặc gây hiểu lầm</td></tr><tr><td>Điều 14</td><td>Quy định các tiêu chuẩn đặc biệt cho hàng hóa và dịch vụ tu luyện: nhà kinh doanh phương pháp tu luyện, dụng cụ tu luyện và hàng hóa năng lượng phải có tư cách đặc biệt, và hàng hóa phải vượt qua chứng nhận an toàn</td></tr><tr><td>Điều 15</td><td>Quy định quy định về điều khoản chuẩn; nhà kinh doanh không được loại trừ hoặc hạn chế quyền của người tiêu dùng, giảm giảm hoặc miễn trừ trách nhiệm của nhà kinh doanh thông qua điều khoản chuẩn</td></tr><tr><td>Điều 16</td><td>Xác định hệ thống trả hàng không có lý do trong bảy ngày; người tiêu dùng mua hàng hóa thông qua các phương thức từ xa như internet có quyền trả hàng hóa trong vòng bảy ngày kể từ ngày nhận hàng hóa</td></tr><tr><td>Điều 17</td><td>Xác định hệ thống ba bảo đảm; nếu hàng hóa hoặc dịch vụ do nhà kinh doanh cung cấp không phù hợp với yêu cầu chất lượng, người tiêu dùng có thể yêu cầu sửa chữa, thay thế hoặc trả hàng theo quy định của nhà nước</td></tr><tr><td>Điều 18</td><td>Xác định hệ thống bồi thường phạt; nếu nhà kinh doanh có hành vi lừa đảo trong việc cung cấp hàng hóa hoặc dịch vụ, họ phải tăng bồi thường cho thiệt hại của người tiêu dùng theo yêu cầu của người tiêu dùng, và số tiền bồi thường tăng thêm phải bằng ba lần giá hàng hóa người tiêu dùng mua hoặc chi phí dịch vụ nhận được</td></tr><tr><td>Điều 19</td><td>Quy định các tổ chức người tiêu dùng; hiệp hội người tiêu dùng và các tổ chức người tiêu dùng khác là các tổ chức xã hội được thành lập theo luật, thực hiện giám sát xã hội đối với hàng hóa và dịch vụ để bảo vệ quyền lợi hợp pháp của người tiêu dùng</td></tr><tr><td>Điều 20</td><td>Quy định các kênh giải quyết tranh chấp người tiêu dùng: đàm phán và hòa giải với nhà kinh doanh, yêu cầu hòa giải của hiệp hội người tiêu dùng, kháng cáo đến các bộ phận hành chính liên quan, yêu cầu trọng tài, khởi kiện ra tòa án</td></tr><tr><td>Điều 21</td><td>Quy định chuyển giao gánh nặng chứng minh trong tranh chấp; đối với hàng hóa bền hoặc dịch vụ như trang trí, nếu người tiêu dùng phát hiện khuyết tật trong vòng sáu tháng kể từ ngày tiếp nhận, nhà kinh doanh chịu gánh nặng chứng minh</td></tr><tr><td>Điều 22</td><td>Quy định trách nhiệm hành chính và hình sự của nhà kinh doanh</td></tr><tr><td>Điều 23</td><td>Quy định ngày hiệu lực và quyền giải thích của luật này</td></tr></tbody></table><h2 id="_5-nam-luat-ho-tro" tabindex="-1">5. Năm Luật Hỗ trợ <a class="header-anchor" href="#_5-nam-luat-ho-tro" aria-label="Permalink to &quot;5. Năm Luật Hỗ trợ&quot;">​</a></h2><h3 id="_5-1-luat-bao-đam-giao-duc" tabindex="-1">5.1 Luật Bảo đảm Giáo dục <a class="header-anchor" href="#_5-1-luat-bao-đam-giao-duc" aria-label="Permalink to &quot;5.1 Luật Bảo đảm Giáo dục&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Số điều khoản</th><th>Nội dung cốt lõi</th></tr></thead><tbody><tr><td>Điều 1</td><td>Mục đích lập pháp: bảo đảm quyền giáo dục bình đẳng của tất cả chúng sinh có tri giác, xây dựng hệ thống giáo dục cộng sinh, và thúc đẩy sự phát triển chung của văn hóa tất cả các chủng tộc</td></tr><tr><td>Điều 2-5</td><td>Xác định nguyên tắc công bằng giáo dục, nguyên tắc giáo dục miễn phí (giai đoạn giáo dục cơ bản), nguyên tắc đa dạng giáo dục, nguyên tắc đổi mới giáo dục</td></tr><tr><td>Điều 6-10</td><td>Quy định kiến trúc hệ thống giáo dục mẫu giáo, giáo dục bắt buộc, giáo dục trung học phổ thông, giáo dục đại học, giáo dục tu luyện</td></tr><tr><td>Điều 11-15</td><td>Quy định các hệ thống đặc biệt cho giáo dục tu luyện: tiêu chuẩn giảng dạy của ba trăm bộ hệ thống, hệ thống sư phụ, hệ thống phân bổ tài nguyên tu luyện</td></tr><tr><td>Điều 16-20</td><td>Quy định quyền và nghĩa vụ của giáo viên, hệ thống tư cách giáo viên, bảo đảm đãi ngộ giáo viên</td></tr><tr><td>Điều 21-25</td><td>Quy định bảo đảm đầu tư giáo dục, xây dựng cơ sở vật chất giáo dục, tin học hóa giáo dục, giáo dục đặc biệt, giáo dục giữa các chủng tộc</td></tr><tr><td>Điều 26-30</td><td>Quy định hệ thống đánh giá giáo dục, hệ thống giám sát giáo dục, trách nhiệm pháp lý và quy định bổ sung</td></tr></tbody></table><h3 id="_5-2-luat-bao-đam-y-te" tabindex="-1">5.2 Luật Bảo đảm Y tế <a class="header-anchor" href="#_5-2-luat-bao-đam-y-te" aria-label="Permalink to &quot;5.2 Luật Bảo đảm Y tế&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Số điều khoản</th><th>Nội dung cốt lõi</th></tr></thead><tbody><tr><td>Điều 1</td><td>Mục đích lập pháp: xây dựng hệ thống bảo đảm y tế toàn dân, bảo đảm quyền sức khỏe của tất cả chúng sinh có tri giác, và nâng cao mức độ sức khỏe tổng thể của tất cả các chủng tộc</td></tr><tr><td>Điều 2-5</td><td>Xác định nguyên tắc bảo hiểm y tế toàn dân, nguyên tắc y tế cơ bản miễn phí, nguyên tắc kết hợp y học Trung Quốc và Tây phương, nguyên tắc bao gồm y tế tu luyện</td></tr><tr><td>Điều 6-10</td><td>Quy định hệ thống bảo hiểm y tế đa cấp độ của bảo hiểm y tế cơ bản, bảo hiểm bệnh nặng, cứu trợ y tế, bảo hiểm sức khỏe thương mại</td></tr><tr><td>Điều 11-15</td><td>Quy định quản lý cơ sở y tế, hệ thống nhân viên y tế, chất lượng và an toàn y tế, các tiêu chuẩn đặc biệt cho y tế tu luyện</td></tr><tr><td>Điều 16-20</td><td>Quy định quản lý dược phẩm, quản lý thiết bị y tế, quản lý sản phẩm y tế năng lượng, hệ thống dược phẩm thiết yếu</td></tr><tr><td>Điều 21-25</td><td>Quy định hệ thống y tế công cộng, phòng ngừa và kiểm soát dịch bệnh, giáo dục sức khỏe, y tế giữa các chủng tộc, bảo đảm y tế cho các nhóm đặc biệt</td></tr><tr><td>Điều 26-30</td><td>Quy định giải quyết tranh chấp y tế, giám sát y tế, trách nhiệm pháp lý và quy định bổ sung</td></tr></tbody></table><h3 id="_5-3-luat-bao-đam-nha-o" tabindex="-1">5.3 Luật Bảo đảm Nhà ở <a class="header-anchor" href="#_5-3-luat-bao-đam-nha-o" aria-label="Permalink to &quot;5.3 Luật Bảo đảm Nhà ở&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Số điều khoản</th><th>Nội dung cốt lõi</th></tr></thead><tbody><tr><td>Điều 1</td><td>Mục đích lập pháp: bảo đảm quyền nhà ở cơ bản của tất cả chúng sinh có tri giác, xây dựng hệ thống bảo đảm nhà ở đa cấp độ, và đạt được nhà ở cho tất cả mọi người</td></tr><tr><td>Điều 2-5</td><td>Xác định nguyên tắc bảo đảm quyền nhà ở, nguyên tắc công bằng nhà ở, nguyên tắc vừa thuê vừa mua, nguyên tắc nhà ở bền vững</td></tr><tr><td>Điều 6-10</td><td>Quy định hệ thống cung cấp nhà ở của nhà ở thuê công cộng, nhà ở thuê bảo đảm, nhà ở sở hữu chung, nhà ở thương mại</td></tr><tr><td>Điều 11-15</td><td>Quy định hệ thống quỹ dự phòng nhà ở, hệ thống trợ cấp nhà ở, chính sách hỗ trợ nhà đầu tiên, chính sách nhà ở đặc biệt cho người tu luyện</td></tr><tr><td>Điều 16-20</td><td>Quy định tiêu chuẩn xây dựng nhà ở, ứng dụng công nghệ vũ trụ trong nhà ở, nhà ở xanh, nhà ở thân thiện với người già và không có rào cản</td></tr><tr><td>Điều 21-25</td><td>Quy định quy định thị trường bất động sản, quy định thị trường thuê nhà ở, quản lý dịch vụ bất động sản, bảo đảm bảo trì nhà ở</td></tr><tr><td>Điều 26-30</td><td>Quy định giám sát bảo đảm nhà ở, trách nhiệm pháp lý và quy định bổ sung</td></tr></tbody></table><h3 id="_5-4-luat-bao-ve-moi-truong" tabindex="-1">5.4 Luật Bảo vệ Môi trường <a class="header-anchor" href="#_5-4-luat-bao-ve-moi-truong" aria-label="Permalink to &quot;5.4 Luật Bảo vệ Môi trường&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Số điều khoản</th><th>Nội dung cốt lõi</th></tr></thead><tbody><tr><td>Điều 1</td><td>Mục đích lập pháp: bảo vệ và cải thiện môi trường, phòng ngừa và kiểm soát ô nhiễm và các công cộng hại khác, bảo đảm sức khỏe cộng đồng, thúc đẩy xây dựng văn minh sinh thái vũ trụ, và thúc đẩy phát triển bền vững</td></tr><tr><td>Điều 2-5</td><td>Xác định nguyên tắc ưu tiên bảo vệ, nguyên tắc phòng ngừa làm chủ, nguyên tắc治理 tổng hợp, nguyên tắc tham gia cộng đồng, nguyên tắc người gây hại chịu trách nhiệm</td></tr><tr><td>Điều 6-10</td><td>Quy định hệ thống giám sát và quản lý môi trường, hệ thống tiêu chuẩn môi trường, hệ thống đánh giá tác động môi trường, hệ thống giám sát môi trường, quản lý môi trường giữa các mặt phẳng</td></tr><tr><td>Điều 11-15</td><td>Quy định phòng ngừa và kiểm soát ô nhiễm không khí, phòng ngừa và kiểm soát ô nhiễm nước, phòng ngừa và kiểm soát ô nhiễm đất, phòng ngừa và kiểm soát ô nhiễm năng lượng, phòng ngừa và kiểm soát ô nhiễm quy luật</td></tr><tr><td>Điều 16-20</td><td>Quy định xử lý chất thải rắn, phòng ngừa và kiểm soát ô nhiễm tiếng ồn, phòng ngừa và kiểm soát ô nhiễm phóng xạ, bảo vệ sinh thái, bảo vệ đa dạng sinh học</td></tr><tr><td>Điều 21-25</td><td>Quy định kiểm soát tác động môi trường của hoạt động tu luyện, bảo vệ sinh thái của khai thác năng lượng, yêu cầu môi trường cho khảo cổ giữa các mặt phẳng</td></tr><tr><td>Điều 26-30</td><td>Quy định công bố thông tin và tham gia cộng đồng, kiện tụng lợi ích cộng đồng môi trường, trách nhiệm pháp lý và quy định bổ sung</td></tr></tbody></table><h3 id="_5-5-luat-chong-đoc-quyen" tabindex="-1">5.5 Luật Chống Độc quyền <a class="header-anchor" href="#_5-5-luat-chong-đoc-quyen" aria-label="Permalink to &quot;5.5 Luật Chống Độc quyền&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Số điều khoản</th><th>Nội dung cốt lõi</th></tr></thead><tbody><tr><td>Điều 1</td><td>Mục đích lập pháp: phòng ngừa và ngăn chặn hành vi độc quyền, bảo vệ cạnh tranh công bằng của thị trường, nâng cao hiệu quả vận hành kinh tế, bảo vệ lợi ích người tiêu dùng và lợi ích công cộng xã hội, và thúc đẩy sự phát triển lành mạnh của kinh tế thị trường cộng sinh</td></tr><tr><td>Điều 2-5</td><td>Xác định lập trường cơ bản của chính sách cạnh tranh, hệ thống xem xét cạnh tranh công bằng, cấm thỏa thuận độc quyền, cấm lạm dụng vị thế thống trị thị trường, kiểm soát tập trung nhà kinh doanh</td></tr><tr><td>Điều 6-10</td><td>Quy định xác định và miễn trừ thỏa thuận độc quyền, thỏa thuận độc quyền ngang, thỏa thuận độc quyền dọc, hành vi độc quyền của hiệp hội ngành</td></tr><tr><td>Điều 11-15</td><td>Quy định xác định vị thế thống trị thị trường, các loại hành vi lạm dụng vị thế thống trị thị trường, cấm định giá cướp bóc</td></tr><tr><td>Điều 16-20</td><td>Quy định tiêu chuẩn khai báo tập trung nhà kinh doanh, thủ tục xem xét, các điều kiện hạn chế bổ sung, quyết định cấm tập trung</td></tr><tr><td>Điều 21-25</td><td>Quy định cấm đặc biệt đối với độc quyền hệ thống tu luyện: cấm độc quyền phương pháp tu luyện, cấm độc quyền tài nguyên tu luyện, cấm độc quyền mạng lưới sư phụ</td></tr><tr><td>Điều 26-30</td><td>Quy định cơ quan thực thi pháp luật chống độc quyền, thủ tục điều tra, trách nhiệm pháp lý, hệ thống khoan hồng và quy định bổ sung</td></tr></tbody></table><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>Chỉ mục Điều khoản Pháp lý là bản đồ tham khảo của hệ thống trị lý theo pháp luật của Văn minh Cộng sinh Mỏ neo. Từ Hiến pháp Cộng sinh với tư cách là luật cơ bản, đến Luật Lao động và Luật Bảo vệ Người tiêu dùng quy định đời sống nhân dân, rồi đến năm luật hỗ trợ, chúng cùng nhau cấu thành một hệ thống pháp luật hoàn chỉnh &quot;lấy Hiến pháp làm thủ lĩnh, luật cơ bản làm xương sống, luật hỗ trợ làm hậu phương&quot;. Hệ thống này bảo đảm mọi hoạt động của văn minh cộng sinh đều vận hành trên quỹ đạo trị lý theo pháp luật, cung cấp bảo đảm thể chế vững chắc cho sự tiến bộ chung của tất cả các chủng tộc.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu Liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu Liên quan&quot;">​</a></h2><ul><li>40-Tổng cương Hiến pháp Cộng sinh</li><li>41-Luật Lao động Cộng sinh</li><li>48-Hệ thống Tư pháp và Cơ chế Tòa án</li></ul>',28)])])}const m=n(g,[["render",u]]);export{p as __pageData,m as default};
